Lemma rmrep_group_hdr_zero : forall st m p gh bs,
  rmrep st m -> (s_groups st) !! p = Some gh ->
  (forall o, 0 <= o < 12 -> exists h, cell_read (get_shadow st (fst p)) (snd p + o) = Unknown h) ->
  length bs = 8%nat ->
  rmrep (del_group p st) (write_to_mem m (wa (conc st p)) bs).
Proof. try hcb.
  intros st m p gh bs H Hp Hunk Hlen.
  pose proof (rmrep_del_group st m p H) as H'.
  destruct H as [WF _].
  destruct (rgroup_conc st p gh WF Hp) as (r & Hr & Hc & Hk & S0 & S16 & Sm & B0 & BC).
  set (st' := del_group p st) in *.
  assert (Hr' : (s_regions st') !! (fst p) = Some r) by exact Hr.
  assert (CR : forall q rq, (s_regions st') !! (fst q) = Some rq -> conc st' q = r_base rq + snd q)
    by (intros q rq E; unfold conc, get_region; rewrite E; reflexivity).
  assert (SG : s_groups st' = delete p (s_groups st)) by reflexivity.
  assert (L8 : Z.of_nat (length bs) = 8) by (rewrite Hlen; reflexivity).
  pose proof (round_up_pg_ge (r_len r)) as RU.
  pose proof (lr_lo_group r Hk) as LLr.
  destruct H' as [WF' [CTX [GL [AR [GR SH]]]]].
  assert (WI : wr_in st' (fst p) (conc st p) (Z.of_nat (length bs))).
  { exists r. rewrite L8, LLr. split; [exact Hr'|]. lia. }
  destruct (rwr_in_image _ _ _ _ WF' WI) as (_ & A0 & A1).
  pose proof (rmrep_ctx_frame st' m (conc st p) bs (fst p) WF' WI CTX) as CTX'.
  pose proof (rmrep_globals_frame st' m (conc st p) bs (fst p) WF' WI GL) as GL'.
  pose proof WF' as (RS & RW & RD & RA & RG).
  unfold rmrep. split; [exact WF'|]. split; [exact CTX'|]. split; [exact GL'|]. split; [|split].
  - intros a ar Ha.
    destruct (RA a ar Ha) as (ra & Hra & Sa0 & Sa4 & Sam & Hka & LLa).
    pose proof (round_up_pg_ge (r_len ra)).
    assert (Hne : fst a <> fst p) by (intros E; rewrite E, Hr' in Hra; congruence).
    apply (rarea_rep_frame st' m (conc st p) bs a ar WF' Ha A0 A1); [|exact (AR a ar Ha)].
    rewrite (CR a ra Hra), L8, Hc.
    destruct (RD _ _ _ _ Hra Hr' Hne) as [D|D]; rewrite ?LLr in D; lia.
  - intros b gb Hb.
    destruct (RG b gb Hb) as (rb & Hrb & Hkb & Sb0 & Sb16 & Sbm).
    pose proof (round_up_pg_ge (r_len rb)).
    assert (Hbp : b <> p) by (intros ->; rewrite SG, lookup_delete_eq in Hb; discriminate).
    apply (rgroup_rep_frame st' m (conc st p) bs b gb A0 A1); [|exact (GR b gb Hb)].
    rewrite (CR b rb Hrb), L8, Hc.
    destruct (N.eq_dec (fst b) (fst p)) as [E|E].
    + rewrite E, Hr' in Hrb. assert (rb = r) by congruence. subst rb.
      assert (snd b <> snd p) by (intros E2; apply Hbp; destruct b, p; cbn in *; congruence).
      pose proof (Z.div_mod (snd b) 16 ltac:(lia)). pose proof (Z.div_mod (snd p) 16 ltac:(lia)).
      lia.
    + destruct (RD _ _ _ _ Hrb Hr' E) as [D|D]; rewrite ?LLr, ?(lr_lo_group rb Hkb) in D; lia.
  - intros rid r0 Hr0 Hk0.
    pose proof (round_up_pg_ge (r_len r0)).
    destruct (N.eq_dec rid (fst p)) as [E|E].
    + subst rid. assert (r0 = r) by congruence. subst r0.
      destruct (SH (fst p) r Hr' Hk0) as [HW HB].
      split; [apply wr_at_write; exact HW|].
      intros o v Ho Hcell. destruct (HB o v Ho Hcell) as [Hb Hv]. split; [|exact Hv].
      assert (Ho2 : o < snd p \/ snd p + 8 <= o).
      { destruct (Z.lt_ge_cases o (snd p)); [left; lia|].
        destruct (Z.lt_ge_cases o (snd p + 8)); [|right; lia].
        exfalso. destruct (Hunk (o - snd p) ltac:(lia)) as [h Hh].
        replace (snd p + (o - snd p)) with o in Hh by lia.
        change (get_shadow st' (fst p)) with (get_shadow st (fst p)) in Hcell.
        rewrite Hh in Hcell. discriminate. }
      apply bytes_at_write_other; [exact Hb|lia|lia|]. rewrite ?L8, ?Hc. cbn. lia.
    + apply (rshadow_rep_frame st' m (conc st p) bs rid r0 A0 A1); [|exact (SH rid r0 Hr0 Hk0)].
      rewrite L8, Hc.
      destruct (RD _ _ _ _ Hr0 Hr' E) as [D|D]; rewrite ?LLr, ?(lr_lo_group r0 Hk0) in D; lia.
Qed.

Lemma rmrep_grp_del_eq : forall st m g p, rmrep (del_group p st) m -> rmrep (grp_del st g p) m.
Proof. try hcb. try hsb. intros. unfold grp_del. apply rmrep_del_slots. exact H. Qed.

End HCW.

